<script setup lang="ts">
import IconButton from './IconButton.vue';
import { ref,onMounted } from 'vue';
import { api,json } from '../api';
const props=defineProps<{world:string}>();
const actor=ref('wan');
const cfg=ref({enabled:false,provider:'auto',model:'',base_url:'',api_key:'',inherit_connection:true,has_key:false});
const busy=ref(false),loading=ref(true),status=ref('');
onMounted(async()=>{try{cfg.value={...cfg.value,...await api<typeof cfg.value>('/api/speech-settings'),api_key:''};}catch(e){status.value=(e as Error).message;}finally{loading.value=false;}});
async function save(){if(busy.value)return;busy.value=true;try{cfg.value={...cfg.value,...await api<typeof cfg.value>('/api/speech-settings',{method:'PUT',body:json(cfg.value)}),api_key:''};status.value='语音模型设置已保存';}catch(e){status.value=(e as Error).message;}finally{busy.value=false;}}
async function test(){if(busy.value)return;busy.value=true;status.value='正在检查连接…';try{status.value=(await api<{message:string}>('/api/speech-settings/test',{method:'POST',body:json({...cfg.value,actor:actor.value}),signal:AbortSignal.timeout(60000)},{world:props.world,channel:'group'})).message;}catch(e){status.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><form class="speech-settings" @submit.prevent="save"><p v-if="loading" class="muted">正在读取…</p><template v-else><label class="switch-row"><span>启用聊天语音</span><input class="switch-input" type="checkbox" v-model="cfg.enabled"></label><label>语音协议<select v-model="cfg.provider"><option value="auto">自动识别</option><option value="mimo">小米 MiMo</option><option value="openai">OpenAI 兼容语音</option></select></label><label>语音模型<input v-model.trim="cfg.model" maxlength="200" placeholder="例如 mimo-v2.5-tts"></label><label class="checks"><input v-model="cfg.inherit_connection" type="checkbox">沿用文字模型的接口和密钥</label><template v-if="!cfg.inherit_connection"><label>语音接口地址<input v-model.trim="cfg.base_url" maxlength="2000" placeholder="https://api.example.com/v1"></label><label>语音 API Key<input v-model.trim="cfg.api_key" type="password" maxlength="4000" autocomplete="new-password" :placeholder="cfg.has_key?'已保存，留空保持不变':'填写语音服务密钥'"></label></template><p class="muted">每位角色的基础音色在各自聊天的“设置 → 人物”中填写。MiMo 普通模型填 Voice ID，voicedesign 模型填音色描述，不自动选择音色。</p><p class="muted">开启后私聊按各自“回复”设置发送文字或语音，群聊仅在明确要求时发送。不自动播放，文字可展开查看。</p><label>测试角色<select v-model="actor"><option value="wan">小婉</option><option value="yan">小研</option><option value="liu">小柳</option></select></label><p class="muted">已填音色时会合成一句测试语音，可能产生费用；未填音色时仅检查模型访问权限，不替你选择音色。</p><p class="feedback" role="status">{{status}}</p><div class="actions"><IconButton icon="connect" label="测试语音连接" @click="test" :busy="busy"/><IconButton icon="save" label="保存语音设置" type="submit" :busy="busy" class="primary"/></div></template></form></template>
